class TodosNotifier extends AsyncNotifier<List<Todo>> {
  @override
  Future<List<Todo>> build() => ref.watch(apiProvider).fetchTodos();

  // ✅ list stays on screen while the server round-trip runs
  Future<void> toggle(Todo t) async {
    state = await AsyncValue.guard(() async {
      await ref.read(apiProvider).setDone(t.id, !t.done);
      return ref.read(apiProvider).fetchTodos();
    });
  }

  // ❌ blanks the list for the duration of the call
  Future<void> toggleFlashy(Todo t) async {
    state = const AsyncLoading();   // previous data thrown away
    state = await AsyncValue.guard(() => ref.read(apiProvider).fetchTodos());
  }

  // ✅ explicit in-flight flag, previous data preserved
  Future<void> toggleWithFlag(Todo t) async {
    state = AsyncLoading<List<Todo>>().copyWithPrevious(state);
    state = await AsyncValue.guard(() => ref.read(apiProvider).fetchTodos());
  }
}

final todosProvider =
    AsyncNotifierProvider<TodosNotifier, List<Todo>>(TodosNotifier.new);

class TodosPage extends ConsumerWidget {
  const TodosPage({super.key});
  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final todos = ref.watch(todosProvider);
    return RefreshIndicator(
      // ✅ the indicator spins until the fetch actually completes
      onRefresh: () => ref.refresh(todosProvider.future),
      child: todos.when(
        // skipLoadingOnRefresh defaults to true: old rows survive the refresh
        data: (list) => ListView(children: [for (final t in list) TodoTile(t)]),
        loading: () => const Center(child: CircularProgressIndicator()),
        error: (e, _) => Center(child: Text('$e')),
      ),
    );
  }
}

