class UploadNotifier extends AutoDisposeAsyncNotifier<Upload> {
  @override
  Future<Upload> build() async {
    final token = CancelToken();
    ref.onDispose(token.cancel);          // ✅ abandon the request on dispose

    final link = ref.keepAlive();         // ✅ survive a quick pop/push
    try {
      final upload = await ref.watch(apiProvider).upload(file, token: token);
      if (!ref.mounted) return upload;    // ✅ nothing left to publish to
      ref.read(analyticsProvider).track('upload_done');
      return upload;
    } finally {
      link.close();                       // provider may be disposed again
    }
  }

  Future<void> retry() async {
    state = await AsyncValue.guard(() => ref.read(apiProvider).retryUpload());
    // ❌ without the guard below this line throws once the screen is gone:
    //    Bad state: Cannot use "ref" after the provider was disposed
    if (!ref.mounted) return;
    ref.read(toastProvider).show('Uploaded');
  }
}

final uploadProvider =
    AsyncNotifierProvider.autoDispose<UploadNotifier, Upload>(UploadNotifier.new);

// Stream subscriptions follow the same rule
final tickerProvider = StreamProvider.autoDispose<int>((ref) {
  final controller = StreamController<int>();
  final timer = Timer.periodic(const Duration(seconds: 1), (t) {
    controller.add(t.tick);
  });
  ref.onDispose(() {                      // ✅ or the timer outlives the screen
    timer.cancel();
    controller.close();
  });
  return controller.stream;
});
